(F/'description.md').write_text('A centered presentation stage with generous side margins, a compact upper title stack, and a twelve by six content grid. Corner illumination, small running furniture, circular placements, and capsule metadata keep the stage calm in both reference modes.\n')
foundation='''.slide{box-sizing:border-box;position:relative;width:1280px;height:720px;overflow:hidden;background:var(--page);color:var(--ink);font-family:var(--font-body);font-weight:var(--weight-body);line-height:var(--body-line);background-image:radial-gradient(ellipse at 0 0,var(--a1-2-soft),var(--page) 60%)}.slide *{box-sizing:border-box}.slide .page{position:relative;z-index:1;height:100%;display:flex;flex-direction:column;padding:var(--margin-y) var(--margin-x);gap:var(--gap-lg)}.slide .head{flex:none;text-align:center;display:flex;flex-direction:column;gap:var(--gap-sm)}.slide .head .kicker,.slide .lockup .kicker{margin:0;color:var(--a1);font-family:var(--font-display);font-size:var(--type-28);font-weight:var(--lead-weight);line-height:var(--lead-line);letter-spacing:var(--lead-track)}.slide .title{margin:0;font-family:var(--font-display);font-size:var(--type-60);font-weight:var(--title-weight);line-height:var(--title-line);letter-spacing:var(--title-track)}.slide .lead{margin:0;font-size:var(--type-24);font-weight:var(--lead-weight);line-height:var(--lead-line);letter-spacing:var(--lead-track);color:var(--n-6)}.slide .body{min-height:0;flex:1;display:grid;grid-template-columns:repeat(12,minmax(0,1fr));grid-template-rows:repeat(6,minmax(0,1fr));gap:var(--gap)}.slide .body>*{min-width:0;min-height:0}.slide .group{display:flex;gap:var(--gap);align-items:stretch}.slide .group>*{flex:1;min-width:0;min-height:0}.slide .group.col,.slide .stack{display:flex;flex-direction:column;gap:var(--gap);min-height:0}.slide .stack>*{min-height:0}.slide .group.two{display:grid;grid-template-columns:repeat(2,minmax(0,1fr))}.slide .group.three{display:grid;grid-template-columns:repeat(3,minmax(0,1fr))}.slide .split{display:grid;grid-template-columns:1fr 2fr;gap:var(--gap)}.slide .split.wide-left{grid-template-columns:2fr 1fr}.slide .top,.slide .foot{position:absolute;left:var(--furn-edge);right:var(--furn-edge);display:flex;justify-content:space-between;align-items:center;font-size:var(--type-14);font-weight:var(--label-weight);letter-spacing:var(--label-track)}.slide .top{top:var(--furn-edge);height:var(--top-h)}.slide .foot{bottom:var(--furn-edge);height:var(--foot-h)}.slide .seat{position:relative;display:flex;align-items:center;justify-content:center;aspect-ratio:1;max-height:100%;min-width:0;min-height:0;background:var(--n-1);border:var(--stroke) solid var(--n-3);border-radius:var(--radius-sm);color:var(--n-6);font-size:var(--type-24)}.slide .seat::after{content:attr(data-ph)}.slide .seat.avatar{border-radius:50%}.slide .seat.portrait{aspect-ratio:4/5}.slide .seat.logo{aspect-ratio:1;border-radius:var(--radius-sm)}.slide .seat.back{position:absolute;inset:0;aspect-ratio:auto;border:0;border-radius:0;z-index:-1}.slide .icon{display:inline-block;width:var(--type-28);height:var(--type-28);flex:none}.slide.cover .page{justify-content:center}.slide.cover .lockup{display:flex;flex-direction:column;gap:var(--gap-lg);max-width:100%}.slide.cover .lockup.at-center{text-align:center;align-self:center;width:100%}.slide.cover .lockup.at-left{text-align:left}.slide.cover .lockup.at-top-left{align-self:flex-start;margin-bottom:auto}.slide.cover .lockup.at-bottom-left{align-self:flex-start;margin-top:auto}.slide.cover .title{font-size:var(--type-88)}.slide.cover .meta{position:absolute;bottom:var(--furn-edge);right:var(--furn-edge);font-size:var(--type-20)}.slide.cover .deco{position:absolute;left:var(--furn-edge);bottom:var(--furn-edge);width:160px;height:160px;border:var(--stroke) solid var(--n-4);border-radius:50%;z-index:-1}.slide .rail{position:absolute;left:var(--furn-edge);top:var(--margin-y);bottom:var(--margin-y);width:var(--rail-w);border-left:var(--stroke) solid var(--n-3)}'''
