# Content fixtures are structural examples, never copied CSS.
mandatory={'card':('confetti',['card-2-quiet','card-3-icon3d','card-3-line','card-3-on','card-4','card-5-tone']),'callout':('annual',['callout','callout-icon','callout-stack']),'chart-area':('annual',['area-1','areas-2','areas-stacked-3','area-3pt']),'chart-bar':('confetti',['bars-12','bars-6','bars-3','bars-h-5','bars-h-8','bars-2']),'chart-donut':('amethyst',['donut','donuts-3','donuts-4','donut-0','donut-100']),'chart-line':('amethyst',['lines-12','lines-6','lines-3','lines-flat'])}
contracts={}
for d in sorted((REF/'samples/annual/elements').iterdir()):
 name=d.name;target=C/'elements'/name;(target/'fixtures').mkdir(parents=True,exist_ok=True)
 meta=json.loads((d/'element.json').read_text());contracts[name]=meta['contract'];(target/'element.json').write_text(json.dumps(meta,indent=2))
 (target/'description.md').write_text(f'{name.replace("-"," ").title()} uses Nocturne\'s isolated figures, restrained orbital outlines, softly bounded panels, and wide breathing room. The accent is assigned to the focal value or active member; supporting labels and connectors remain neutral. The composition steps down deliberately in smaller grid allocations.\n')
 fs=sorted((d/'fixtures').glob('*.html'))
 # All annual structural fixtures are retained; mandated examples replace same-name fixtures.
 for p in fs:
  s=re.sub(r'data-el="(?:annual|amethyst|confetti)-', 'data-el="nocturne-',p.read_text())
  # Contract asks full-grid fixture placements. This changes placement only, never mandated markup/data.
  if name not in mandatory:s=re.sub(r'grid-column:[^;"\n]*;\s*grid-row:[^;"\n]*','grid-column:1 / span 12; grid-row:1 / span 6',s,count=1)
  (target/'fixtures'/p.name).write_text(s)
 if name in mandatory:
  sample,files=mandatory[name]
  for n in files:
   p=REF/f'samples/{sample}/elements/{name}/fixtures/{n}.html';s=re.sub(r'data-el="(?:annual|amethyst|confetti)-','data-el="nocturne-',p.read_text());(target/'fixtures'/p.name).write_text(s)
 # Add second fixture for categories with one source.
 if len(list((target/'fixtures').glob('*.html')))<2:
  p=next((target/'fixtures').glob('*.html'));s=p.read_text().replace('2055','2079').replace('2056','2080').replace('베이직','성장 지원 플랜').replace('제조','고객 경험 개선').replace('매출','해외 매출').replace('영업','신규 사업');(target/'fixtures'/'extended.html').write_text(s)
 # Ensure nested element scopes explicitly exist where annual fixture omitted them.
 for p in (target/'fixtures').glob('*.html'):
  s=p.read_text()
  for cls,folder in [('list','list'),('tag','tag')]:
   s=re.sub(r'(<(?:div|ul|span)\b[^>]*class="'+cls+r'(?: [^"]*)?"(?![^>]*data-el))',r'\1 data-el="nocturne-'+folder+'"',s)
  p.write_text(s)
print('Initialized',len(contracts),'element folders')
