assert set(styles)==set(contracts),(set(contracts)-set(styles))
for name,css in styles.items():
 scope=f'[data-el="nocturne-{name}"]'
 base='''R{box-sizing:border-box;position:relative;min-width:0;min-height:0;container-type:size;font-family:var(--font-body);font-size:var(--type-20);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track)}R :is(.name,.note,.kick,.fig){margin:0;overflow-wrap:anywhere}R .name{font-weight:var(--name-weight);line-height:var(--name-line);letter-spacing:var(--name-track)}R .note{font-size:var(--type-18);font-weight:var(--body-weight);line-height:var(--body-line);letter-spacing:var(--body-track);color:var(--n-6)}R .kick{font-size:var(--type-18);font-weight:var(--label-weight);line-height:var(--label-line);letter-spacing:var(--label-track);color:var(--a1)}R .fig{font-family:var(--font-display);font-weight:var(--figure-weight);line-height:var(--figure-line);letter-spacing:var(--figure-track);font-variant-numeric:tabular-nums}R .fig small{font-size:var(--type-24);font-weight:var(--label-weight)}R .icon{display:inline-block;width:var(--type-28);height:var(--type-28);flex:none}'''
 css=(base+css).replace('R',scope).replace('rgba(0,0,0,0)','transparent').replace('#000','var(--ink)')
 # At least one deliberate container step per element, even for compact inline atoms.
 if '@container' not in css:css+=f'@container(max-width:360px){{{scope} .name{{font-size:var(--type-18)}}{scope} .note{{font-size:var(--type-14)}}}}'
 (C/'elements'/name/'element.css').write_text(css+'\n')
# A monospace font is an explicit, legal font token extension for code.
kit['extensions']['--nocturne-font-code']='font';(C/'kit/kit.json').write_text(json.dumps(kit,indent=2));p=C/'kit/css/tokens.css';p.write_text(p.read_text().replace('.slide {','.slide {\n --nocturne-font-code: \'Nanum Gothic Coding\';',1));p=C/'elements/code/element.css';p.write_text(p.read_text().replace('font-family:var(--font-body);font-variant-ligatures','font-family:var(--nocturne-font-code);font-variant-ligatures'))
print('Authored CSS for all',len(styles),'elements')
